// SPDX-License-Identifier: AGPL-3.0-only
//! Single declaration of enforceable values in the reviewed foundation inventory.
//! L1b adds pinned source sites without claiming whole-Python review closure.
//! Run budget-model's inventory_gate example to see where the inventory stands. Since RU-053 it is a
//! report, not a gate: it prints the inventory counts and a closure status line (PASS, or the
//! violation count and the first few violations) and exits 0 whenever the report was produced.
//! Read that closure line before claiming inventory completion; an unlisted bound still needs
//! review and provenance before its consumer lands.
use crate::{Bytes, Entries, Permille, Refusal, Span};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Phase {
    Compile,
    Publish,
    Start,
    Stop,
    Close,
    Relay,
    FirstToken,
    Control,
    Cleanup,
    /// Inventory-only operational site; L2 has not mapped a qualified phase.
    Unclassified,
}
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Provenance {
    Source(&'static str),
    Measured(&'static str),
    Blocked(&'static str),
}
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Purpose {
    Policy,
    Operational(Phase),
    /// Progress can renew this idle window: it is not an end-to-end bound.
    ProgressWindow(Phase),
    IncidentObservation,
    HistoricalFault,
    Resource,
}
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Formula {
    LeaseRenewal,
    CloseWaitSum,
    StartupWaitSum,
    RestartObservationFloor,
    RolloverLead,
    EffectiveStop,
    CleanupFanout,
    PeerCleanupAdvertisement,
    CommandCleanup,
}
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Value {
    Duration(Span),
    Storage(Bytes),
    Count(Entries),
    BytesPerSecond(Bytes),
    /// Integral count-rate policy operands, not counts or durations.
    CountPerSecond(Entries),
    /// Dimensionless ratio (RU-024): permille, exact decimal fractions only.
    Ratio(Permille),
    Derived(Formula),
    Blocked,
}
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct BudgetEntry {
    pub id: BudgetId,
    pub value: Value,
    pub purpose: Purpose,
    pub provenance: Provenance,
}

macro_rules! table {
    ($( $id:ident => ($value:expr, $purpose:expr, $provenance:expr) ),+ $(,)?) => {
        /// Stable named call-site identifiers; numeric discriminants are not a wire format.
        #[derive(Clone, Copy, Debug, Eq, PartialEq, Ord, PartialOrd)]
        pub enum BudgetId { $( $id ),+ }
        pub const BUDGET_TABLE: &[BudgetEntry] = &[
            $( BudgetEntry { id: BudgetId::$id, value: $value, purpose: $purpose, provenance: $provenance } ),+
        ];
        impl BudgetId {
            /// Stable spelling for inventory/call-site crosswalks, not a numeric ABI.
            pub const fn name(self) -> &'static str {
                match self { $( Self::$id => stringify!($id) ),+ }
            }
            pub fn from_name(name: &str) -> Option<Self> {
                match name { $( stringify!($id) => Some(Self::$id), )+ _ => None }
            }
            pub const fn entry(self) -> BudgetEntry {
                match self { $( Self::$id => BudgetEntry { id: self, value: $value, purpose: $purpose, provenance: $provenance } ),+ }
            }
        }
    }
}
