// Compile-time declaration coherence; this intentionally does not assert that
// the incoherent F16 close/start defaults are safe or latency-qualified.
const _: () = {
    if let (Duration(reserve), Duration(ceiling), Duration(margin)) = (
        BudgetId::WorkerCleanupReserve.entry().value,
        BudgetId::ExecutionCeilingLead.entry().value,
        BudgetId::RolloverMargin.entry().value,
    ) {
        assert!(reserve.millis() < ceiling.millis());
        assert!(ceiling.millis() < margin.millis());
    } else {
        panic!("worker declaration units changed");
    }
    if let (Count(keep), Count(cap)) = (
        BudgetId::ReplayKeep.entry().value,
        BudgetId::ReplayCapacity.entry().value,
    ) {
        assert!(keep.get() < cap.get());
    } else {
        panic!("replay declaration units changed");
    }
};

impl BudgetId {
    /// Runtime declaration access. Keep `entry()` const for declaration inspection;
    /// all value evaluation, including recursive formulas, uses this accessor.
    pub fn read_entry(self) -> BudgetEntry {
        let entry = self.entry();
        #[cfg(feature = "trace-reads")]
        crate::reads::record(entry);
        entry
    }
    pub fn count(self) -> Result<Entries, Refusal> {
        match self.read_entry().value {
            Count(n) => Ok(n),
            _ => Err(Refusal::WrongUnit(self)),
        }
    }
    /// Wall-dependent derived policy; peers affect the nominal explicit close waits.
    pub fn wall_span(self, wall: Span, peers: Entries) -> Result<Span, Refusal> {
        use BudgetId::*;
        match self.read_entry().value {
            Derived(Formula::RolloverLead) => Ok(RolloverMargin
                .span(peers)?
                .max(ExecutionCeilingLead.span(peers)?)
                .min(wall.checked_div(HalfWallDivisor.count()?.get())?)),
            Derived(Formula::EffectiveStop) => Ok(EffectiveRolloverLead
                .wall_span(wall, peers)?
                .checked_sub(WorkerCleanupReserve.span(peers)?)?
                .min(ConfiguredCloseWaitSum.span(peers)?)),
            _ => self.span(peers),
        }
    }
    pub fn bytes(self) -> Result<Bytes, Refusal> {
        match self.read_entry().value {
            Storage(n) => Ok(n),
            _ => Err(Refusal::WrongUnit(self)),
        }
    }
    /// Explicit waits only. This does NOT turn ConfiguredCloseWaitSum into a finite bound.
    pub fn span(self, peers: Entries) -> Result<Span, Refusal> {
        use BudgetId::*;
        let read = |id: BudgetId| id.span(peers);
        match self.read_entry().value {
            Duration(n) => Ok(n),
            Derived(Formula::CleanupFanout) => read(CancelAndCleanup)?
                .checked_sub(read(PyMyceliumDeadlinesCleanupFallbackReserveSecondsL193)?),
            Derived(Formula::PeerCleanupAdvertisement) => read(PyRouteCleanupFanout)?
                .checked_sub(read(
                    PyMyceliumDeadlinesPeerCleanupBoundTransportMarginMsL342,
                )?)?
                .checked_sub(read(
                    PyMyceliumDeadlinesPeerAdvertisedCleanupBoundSlackMsL349,
                )?),
            Derived(Formula::CommandCleanup) => read(CancelAndCleanup),
            Derived(Formula::LeaseRenewal) => {
                read(MembershipTtl)?.checked_div(RenewalDivisor.count()?.get())
            }
            Derived(Formula::CloseWaitSum) => {
                let per_peer = read(NodeSession)?
                    .checked_mul(StopSendsPerPeer.count()?.get())?
                    .checked_add(read(StageCleanup)?)?;
                read(RegistryPoll)?
                    .checked_add(read(RouterClose)?)?
                    .checked_add(read(CancelAndCleanup)?)?
                    .checked_add(read(RouteMonitorJoin)?)?
                    .checked_add(per_peer.checked_mul(peers.get())?)
            }
            Derived(Formula::StartupWaitSum) => [Compile, Slices, Publish, Targets, Serving]
                .into_iter()
                .try_fold(Span::ZERO, |sum, id| sum.checked_add(read(id)?)),
            Derived(Formula::RestartObservationFloor) => read(ObservedStop)?
                .checked_add(read(ObservedStart)?)?
                .checked_mul(P99Multiplier.count()?.get())?
                .checked_add(read(WorkerCleanupReserve)?),
            Derived(Formula::RolloverLead | Formula::EffectiveStop) => {
                Err(Refusal::MissingBudgetContext(self))
            }
            Value::Blocked => match self.read_entry().purpose {
                Operational(phase) => Err(Refusal::BlockedNoP99(phase)),
                _ => Err(Refusal::WrongUnit(self)),
            },
            _ => Err(Refusal::WrongUnit(self)),
        }
    }
}
